def solution(nxt):
    if not nxt:
        return -1
    # Phase 1: slow moves 1 hop, fast moves 2. They meet only if there is a loop.
    slow = fast = 0
    while True:
        if nxt[fast] == -1 or nxt[nxt[fast]] == -1:
            return -1                        # fast fell off the end: no loop
        slow = nxt[slow]
        fast = nxt[nxt[fast]]
        if slow == fast:
            break
    # Phase 2: the head and the meeting point are the same distance from the loop start.
    slow = 0
    while slow != fast:
        slow = nxt[slow]
        fast = nxt[fast]
    return slow
